if (items.length > 0) {
  const linhas = items
    .filter(p => p && (p.nome || p.Produto || p.produto || p.Nome))
    .map(p => {
      const nome      = p.nome || p.Produto || p.produto || p.Nome || 'Produto';
      const preco     = p.preco || p.Preco || p.valor || p.Valor || 'Consulte';
      const descricao = p.descricao || p.Descricao || p.desc || '';
      if (tipoProduto === 'digital' || tipoProduto === 'infoproduto') {
        const link = p.link || p.Link || '';
        return 'Produto: ' + nome + ' | Preco: R$' + preco + (descricao ? ' | ' + descricao : '') + (link ? ' | Entrega: ' + link : '');
      } else {
        const estoque = p.estoque || p.Estoque || '';
        const duracao = p.duracao || p.Duracao || p.tempo || p.Tempo || '';
        return 'Produto: ' + nome + ' | Preco: R$' + preco + (estoque ? ' | Estoque: ' + estoque : '') + (descricao ? ' | ' + descricao : '') + (duracao ? ' | Prazo: ' + duracao : '');
      }
    });
  catalogo = linhas.join('\n');
}

return [{ json: { catalogo_texto: catalogo || 'Catalogo nao disponivel no momento.' } }];

const txt = v => (v == null || v === '') ? '' : String(v).trim();

let filtroData = {};
try { filtroData = $('Filtro + Extrair').first().json; } catch { filtroData = {}; }

const telefone = txt(filtroData.telefone);
const pushName = txt(filtroData.pushName);
const fromMe = filtroData.fromMe ?? false;
const instanciaWebhook = txt(filtroData.instance);
const text = txt(filtroData.text);
const messageId = txt(filtroData.messageId);

let rawNegocio = [];
try { rawNegocio = $('Carregar Dados Negocio').all().map(i => i.json); } catch { rawNegocio = []; }

if (rawNegocio.length === 0) {
  return [{ json: { erro: 'Neg?cio n?o encontrado.', instancia_recebida: instanciaWebhook } }];
}

const n = rawNegocio[0];
const inst = instanciaWebhook || txt(n.instancia_whatsapp);

let servicosLista = 'Consultar cat?logo.';
try {
  const raw = n.servicos_json || '';
  if (raw && raw !== '[]') {
    let s = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (Array.isArray(s) && s.length > 0) {
      servicosLista = s.map(x => `- ${x.nome || 'Produto'}: R$ ${x.preco || 'consulte'}${x.duracao ? ' (' + x.duracao + ' min)' : ''}`).join('\n');
    }
  }
} catch { if (n.servicos_json) servicosLista = n.servicos_json; }

// Montar info de pagamento
let infoPagamento = '';
if (txt(n.chave_pix)) {
  infoPagamento += 'PIX dispon?vel: ' + txt(n.tipo_chave_pix).toUpperCase() + ': ' + txt(n.chave_pix);
  if (txt(n.nome_titular_pix)) infoPagamento += ' | Titular: ' + txt(n.nome_titular_pix);
  if (txt(n.banco_pix)) infoPagamento += ' | Banco: ' + txt(n.banco_pix);
}
if (n.aceita_cartao && txt(n.link_checkout)) {
  infoPagamento += (infoPagamento ? ' | ' : '') + 'Cart?o/Boleto via link de checkout';
}

return [{ json: {
  instancia: inst,
  cliente_id: n.cliente_id ?? n.id ?? null,
  session_id: `${inst}_${telefone}`,
  nome_empresa: txt(n.nome_empresa) || 'Empresa',
  nome_proprietario: txt(n.nome_proprietario),
  telefone_empresa: txt(n.telefone),
  endereco: txt(n.endereco),
  horario_funcionamento: txt(n.horario_funcionamento) || 'Hor?rio comercial',
  formas_pagamento: txt(n.formas_pagamento) || 'Consulte',
  informacoes_extras: txt(n.informacoes_extras),
  nome_atendente_ia: txt(n.nome_atendente_ia) || 'Assistente de Vendas',
  tom_voz: txt(n.tom_voz) || 'Consultiva, calorosa e persuasiva',
  servicos_lista: servicosLista,
  telefone, pushName, fromMe, text, messageId,
  telefone_proprietario: txt(n.telefone),
  remoteJid: telefone + '@s.whatsapp.net',
  evo_api_url: txt(n.evo_api_url) || 'https://evo.upviaagentes.com',
  evo_api_key: txt(n.evo_api_key) || '3gl0eq56t0ahsh3m5lx7ruv8i764qcvd',
  google_sheet_id: txt(n.google_sheet_id) || txt(n.catalogo_sheets_id),
  catalogo_sheets_id: txt(n.catalogo_sheets_id),
  link_vendas: txt(n.link_vendas),
  tipo_produto: txt(n.tipo_produto) || 'fisico',
  chave_pix: txt(n.chave_pix),
  tipo_chave_pix: txt(n.tipo_chave_pix),
  nome_titular_pix: txt(n.nome_titular_pix),
  banco_pix: txt(n.banco_pix),
  aceita_cartao: n.aceita_cartao || false,
  link_checkout: txt(n.link_checkout),
  msg_pos_venda: txt(n.msg_pos_venda),
  info_pagamento: infoPagamento
} }];
